changeSet.sql:
CREATE TABLE roles ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
code varchar(255) NOT NULL UNIQUE, name varchar(255) NOT NULL, description varchar(255), system_role boolean NOT NULL,
PRIMARY KEY (id) );

changeSet.rollback:
